P.QAUD = {"seeker":["इस अंश का मेरे वर्तमान जीवन से क्या संबंध है?","मैं अभी मसीही नहीं हूँ। इन शब्दों का मेरे लिए क्या अर्थ है?","क्या परमेश्वर सचमुच है? विश्वास करने के क्या कारण हैं?","बाइबल क्यों कहती है कि हर किसी को यीशु की आवश्यकता है?","मुझ पर बहुत तनाव है। बाइबल मुझे कौन-सी व्यावहारिक सहायता देती है?","यहाँ “पाप” का क्या अर्थ है? क्या इसका मुझसे कोई संबंध है?","मसीही लोग अक्सर “अनुग्रह” की बात करते हैं। सरल भाषा में इसका क्या मतलब है?","यदि मैं और जानना चाहूँ, तो कहाँ से शुरू करूँ?"],"teen":["इस अंश का मेरी रोज़मर्रा की ज़िंदगी, यानी स्कूल, दोस्तों और फ़ोन से क्या संबंध है?","यदि यह अंश परमेश्वर की ओर से सिर्फ़ मेरे लिए एक संदेश होता, तो वह क्या कहता?","सब लोग यही करते हैं। अगर मैं न करूँ तो क्या यह अजीब है? शास्त्र इस बारे में क्या कहता है?","क्या आप इस अंश को किसी गेम या फ़िल्म की मिसाल से समझा सकते हैं?","इस अंश में कौन-सी बात चौंकाने वाली या कम जानी-पहचानी है?","परीक्षा का दबाव बहुत है। यह अंश मुझे कैसी शक्ति देता है?","मैं किसी को माफ़ नहीं कर पा रहा हूँ। यह अंश मेरी कैसे मदद करता है?","क्या परमेश्वर सचमुच मुझे देखता है? मुझे प्रेम के योग्य क्या बनाता है?"],"kid":["यह कहानी किस बारे में है? कृपया मुझे सुनाइए।","इस कहानी में परमेश्वर ने क्या किया?","क्या यीशु मुझसे प्रेम करते हैं? मुझे यह कैसे पता चलेगा?","इस कहानी में सबसे बहादुर कौन है? और क्यों?","मैं इस कहानी के लोगों जैसा कैसे बन सकता हूँ?","मुझे याद करने के लिए एक छोटा-सा वचन सिखाइए।","मेरा अपने सबसे अच्छे दोस्त से झगड़ा हो गया है। यीशु क्या करते?","क्या आप मुझे एक छोटी-सी प्रार्थना सिखा सकते हैं?"]};
P.AUD2 = {"elder":{"q":["सबसे सरल शब्दों में बताइए, यह अंश क्या कह रहा है?","यह अंश बुज़ुर्गों को कैसी सांत्वना देता है?","मेरा शरीर धीरे-धीरे कमज़ोर होता जा रहा है। परमेश्वर मेरी देखभाल कैसे करता है?","मैं अक्सर अकेलापन महसूस करता हूँ। यह अंश मुझे क्या देता है?","मैं अपना विश्वास अपने बच्चों और पोते-पोतियों तक कैसे पहुँचाऊँ?","कुछ बातें हैं जिन्हें मैं अब भी छोड़ नहीं पाता। यह अंश उन्हें प्रभु को सौंपना कैसे सिखाता है?","मैं बूढ़ा हो गया हूँ। अब भी मैं परमेश्वर के लिए क्या कर सकता हूँ?","कृपया मेरे लिए एक छोटी प्रार्थना लिख दीजिए, जो मैं प्रभु के सामने रख सकूँ।"],"fu":["स्वास्थ्य","अकेलापन","परिवार","सौंप देना","आशा","प्रार्थना"],"rw":["आपने पूरी पुस्तक {nm} पढ़ ली!","दिन-प्रतिदिन चलते हुए आप यहाँ तक पहुँचे हैं। परमेश्वर इस विश्वासयोग्यता को स्मरण रखता है, और यह हम छोटों के लिए एक आदर्श है।"],"res":["कोई बात नहीं, धीरे-धीरे चलिए। एक बार फिर पढ़ने से अर्थ और साफ़ हो जाएगा।","बहुत अच्छे! आपको इस अध्याय की बहुत-सी बातें याद हैं।","बहुत बढ़िया! परमेश्वर का वचन आपके हृदय में जीवित है।"]},"single_parent":{"q":["मैं अकेले परिवार का बोझ उठा रहा हूँ। यह अंश मुझे कैसी सांत्वना देता है?","मैं बहुत थक गया हूँ और लगता है कि मैं अपने बच्चों के प्रति अपना कर्तव्य पूरा नहीं कर पा रहा। परमेश्वर मुझे किस दृष्टि से देखता है?","परमेश्वर अनाथों और विधवाओं की चिंता कैसे करता है, और इसका मेरे लिए क्या अर्थ है?","पैसे की बहुत तंगी है। यह अंश मुझे क्या देता है?","मेरा बच्चा ज़बान लड़ाता है और उसकी भावनाएँ बहुत तीव्र हैं। मुझे क्या करना चाहिए?","मुझे समझ नहीं आता कि अपने बच्चे से उसके पिता (या माँ) के हमारे साथ न होने के बारे में कैसे बात करूँ।","मैं बहुत अकेला महसूस करता हूँ। कलीसिया या विश्वासी भाई-बहनों से मदद कैसे माँगूँ?","कृपया मेरे लिए एक छोटी प्रार्थना लिख दीजिए, जो मैं पाँच मिनट में कर सकूँ।"],"fu":["थकान","बच्चे","आर्थिक स्थिति","मदद माँगना","आशा","प्रार्थना"],"rw":["आपने पूरी पुस्तक {nm} पढ़ ली!","अकेले परिवार का बोझ उठाते हुए भी बाइबल पढ़ते रहना आसान नहीं है। परमेश्वर आपके हर कदम को देखता है, और वह आपके साथ है।"],"res":["कोई बात नहीं, आपने बहुत मेहनत की है। जब समय मिले, फिर से पढ़ लीजिए।","बहुत अच्छे! इतनी व्यस्तता में भी आपको बहुत कुछ याद है।","बहुत बढ़िया! परमेश्वर का वचन आपको थामे हुए है।"]},"single":{"q":["एक अविवाहित व्यक्ति के रूप में, यह अंश मुझसे क्या कहता है?","मैं अकेलापन महसूस करता हूँ। यह अंश मुझे क्या देता है?","मसीह में मैं कौन हूँ, और मेरा मूल्य क्या है?","प्रतीक्षा करते हुए मैं परमेश्वर पर भरोसा कैसे रखूँ?","रिश्तों के बारे में बाइबल क्या बुद्धि देती है?","एक अविवाहित व्यक्ति का समय और ऊर्जा परमेश्वर के लिए कैसे उपयोग हो सकती है?","मैं कलीसिया में और मित्रों के साथ अच्छे संबंध कैसे बनाऊँ?","कृपया एक अविवाहित व्यक्ति के लिए एक छोटी प्रार्थना लिख दीजिए।"],"fu":["अकेलापन","पहचान","प्रतीक्षा","रिश्ते","जीवन का उद्देश्य","प्रार्थना"],"rw":["आपने पूरी पुस्तक {nm} पढ़ ली!","आप अकेले भी दृढ़ता से चलते रहे हैं, और परमेश्वर के सामने आपके दिन पूरे और प्रिय हैं।"],"res":["कोई बात नहीं, धीरे-धीरे चलिए। एक बार फिर पढ़ने से अर्थ और साफ़ हो जाएगा।","बहुत अच्छे! आप इस अध्याय का सार समझ गए हैं।","बहुत बढ़िया! आप परिश्रमी हैं, और परमेश्वर का वचन आप में जड़ पकड़ रहा है।"]},"parent":{"q":["माता-पिता होने के नाते यह अंश मुझे क्या याद दिलाता है?","मेरा बच्चा बात नहीं सुनता और उसकी भावनाएँ बहुत तीव्र हैं। मुझे कैसे व्यवहार करना चाहिए?","अनुशासन और अनुग्रह के बीच संतुलन कैसे रखूँ?","किशोर बच्चे से अच्छी तरह बातचीत कैसे करूँ?","मैं अक्सर अपने बच्चे पर क्रोधित हो जाता हूँ और फिर मुझे अपराध-बोध होता है। अब मैं क्या करूँ?","मैं अपने बच्चे को केवल कलीसिया जाने तक सीमित न रखकर परमेश्वर को जानने तक कैसे ले चलूँ?","मेरे जीवनसाथी और मेरे बीच बच्चों के पालन-पोषण को लेकर मतभेद है। यह अंश क्या कहता है?","कृपया मेरे बच्चे के लिए आशीष की एक छोटी प्रार्थना लिख दीजिए।"],"fu":["संवाद","अनुशासन","अपराध-बोध","जीवनसाथी","विश्वास","प्रार्थना"],"rw":["आपने पूरी पुस्तक {nm} पढ़ ली!","बच्चों के पालन-पोषण की व्यस्तता के बीच हर दिन बाइबल पढ़ना, यही आप उन्हें सबसे अच्छा आदर्श दे सकते हैं।"],"res":["कोई बात नहीं, धीरे-धीरे चलिए। जब अवसर मिले, फिर से पढ़ लीजिए।","बहुत अच्छे! आप इस अध्याय का सार समझ गए हैं।","बहुत बढ़िया! परमेश्वर का वचन आपके घर में जड़ पकड़ रहा है।"]},"couple":{"q":["पति-पत्नी के रूप में यह अंश हमसे क्या कहता है?","हर झगड़े के बाद हम एक-दूसरे से ठंडे पड़ जाते हैं। हम में से कोई एक मेल-मिलाप के लिए पहला कदम कैसे उठाए?","मैं अपने मन की बात ऐसे कैसे कहूँ कि मेरा जीवनसाथी उसे सुन सके?","मेरे जीवनसाथी ने मुझे ठेस पहुँचाई है। क्या मुझे सचमुच क्षमा करना ही चाहिए?","पैसों और घर के कामों को लेकर हमारे बीच मतभेद है। हमें क्या करना चाहिए?","हम एक साथ प्रार्थना कैसे करें और साथ मिलकर परमेश्वर के निकट कैसे आएँ?","जीवन की व्यस्तता ने हमें एक-दूसरे से दूर कर दिया है। हम फिर से करीब कैसे आएँ?","कृपया हमारे विवाह के लिए आशीष की एक छोटी प्रार्थना लिख दीजिए।"],"fu":["संवाद","क्षमा","आत्मीयता","एक मन","साथ पढ़ना","प्रार्थना"],"rw":["आप दोनों ने साथ मिलकर पूरी पुस्तक {nm} पढ़ ली!","जो दंपती साथ मिलकर परमेश्वर के वचन के निकट आता है, वह दृढ़ नींव पर खड़ा होता है।"],"res":["कोई बात नहीं, धीरे-धीरे चलिए। किसी शाम फिर से साथ पढ़ लीजिए।","बहुत अच्छे! आप दोनों इस अध्याय का सार समझ गए हैं।","बहुत बढ़िया! परमेश्वर का वचन आपके विवाह में जड़ पकड़ रहा है।"]},"pastor":{"q":["सेवकाई में यह अंश मुझसे क्या कहता है?","कृपया इस अंश के लिए संदेश की रूपरेखा और शुरुआती बिंदु खोजने में मेरी मदद कीजिए।","मैं बहुत थका हुआ हूँ और पूरी तरह थक जाने के कगार पर हूँ। यह अंश मुझे कैसी सांत्वना देता है?","कलीसिया में आलोचना और ग़लतफ़हमी का सामना कैसे करूँ?","एक मन होकर टीम की अगुवाई करने के बारे में यह अंश क्या कहता है?","व्यस्त सेवकाई के बीच मैं परमेश्वर के साथ अपने निजी चलन को कैसे सुरक्षित रखूँ?","कमज़ोरों, घायलों और कलीसिया छोड़ चुके लोगों की चरवाही कैसे करूँ?","कृपया कलीसिया और मेरे सहकर्मियों के लिए मध्यस्थता की एक छोटी प्रार्थना लिख दीजिए।"],"fu":["संदेश","चरवाही","टीम","विश्राम","आत्मिक युद्ध","मध्यस्थता"],"rw":["आपने पूरी पुस्तक {nm} पढ़ ली!","व्यस्त सेवकाई के बीच परमेश्वर के वचन के निकट बने रहना ही चरवाही की सबसे गहरी जड़ है।"],"res":["कोई बात नहीं, धीरे-धीरे चलिए। जब अवसर मिले, फिर से पढ़ लीजिए।","बहुत अच्छे! आप इस अध्याय का सार समझ गए हैं।","बहुत बढ़िया! परमेश्वर का वचन पहले चरवाहे को खिलाता है, फिर झुंड तक बह निकलता है।"]}};
